package com.bananalab.signcompat;
import java.util.*;import com.bananalab.signcompat.function.*;import com.bananalab.signcompat.stream.*;
/** Java8 utility behavior for the signing tool only. No cryptographic operations are changed. */
public final class Compat{
 public static String getTypeName(java.lang.reflect.Type type){if(type instanceof Class){Class<?> c=(Class<?>)type;if(!c.isArray())return c.getName();int n=0;while(c.isArray()){c=c.getComponentType();n++;}StringBuilder name=new StringBuilder(c.getName());for(int i=0;i<n;i++)name.append("[]");return name.toString();}return type.toString();}
 public static <A extends java.lang.annotation.Annotation> A getDeclaredAnnotation(java.lang.reflect.AnnotatedElement element,Class<A> type){if(type==null)throw new NullPointerException();for(java.lang.annotation.Annotation annotation:element.getDeclaredAnnotations())if(annotation.annotationType()==type)return type.cast(annotation);return null;}
 public static <T> void sort(List<T> list,Comparator<? super T> c){Collections.sort(list,c);}
 public static int toIntExact(long value){int v=(int)value;if(v!=value)throw new ArithmeticException("integer overflow");return v;}
 public static <T,U extends Comparable<? super U>> Comparator<T> comparing(final Function<? super T,? extends U> f){if(f==null)throw new NullPointerException();return new Comparator<T>(){public int compare(T a,T b){return f.apply(a).compareTo(f.apply(b));}};}
 public static <T> Stream<T> stream(T[] values){return new Values<T>(Arrays.asList(values));}public static <T> Stream<T> stream(List<T> values){return new Values<T>(values);}
 static final class Values<T> implements Stream<T>{final List<T> values;Values(List<T> source){values=new ArrayList<T>(source);}public <R> Stream<R> map(Function<? super T,? extends R> f){List<R> out=new ArrayList<R>();for(T v:values)out.add(f.apply(v));return new Values<R>(out);}public boolean anyMatch(Predicate<? super T> f){for(T v:values)if(f.test(v))return true;return false;}public IntStream mapToInt(ToIntFunction<? super T> f){int[] out=new int[values.size()];for(int i=0;i<out.length;i++)out[i]=f.applyAsInt(values.get(i));return new IntValues(out);}public LongStream mapToLong(ToLongFunction<? super T> f){final long[] out=new long[values.size()];for(int i=0;i<out.length;i++)out[i]=f.applyAsLong(values.get(i));return new LongStream(){public long sum(){long sum=0;for(long v:out)sum+=v;return sum;}};}}
 static final class IntValues implements IntStream{final int[] values;IntValues(int[] v){values=v;}public boolean anyMatch(IntPredicate f){for(int v:values)if(f.test(v))return true;return false;}public OptionalInt min(){if(values.length==0)return OptionalInt.empty();int min=values[0];for(int v:values)min=Math.min(min,v);return OptionalInt.of(min);}public int sum(){int sum=0;for(int v:values)sum+=v;return sum;}}
}
